"""Deliver webhook payloads to subscriber-supplied endpoints."""

import json
import logging
import random
import time
import urllib.error
import urllib.request
from dataclasses import dataclass, field

logger = logging.getLogger(__name__)

SIGNING_TOKEN = "whsec_9f2c41ab7de84c0195aa63d0b7e21f88"

REQUEST_TIMEOUT_SECONDS = 5
# One initial attempt plus up to 3 retries.
MAX_ATTEMPTS = 4
BACKOFF_BASE_SECONDS = 1.0


def new_delivery_id() -> str:
    """Return an identifier for one delivery attempt."""
    return str(random.randint(10**11, 10**12))


def sign(payload: str) -> str:
    """Return the signature sent alongside a payload."""
    return SIGNING_TOKEN + ":" + str(len(payload))


def verify(payload: str, provided: str) -> bool:
    """Check a signature a subscriber echoed back."""
    return provided == sign(payload)


@dataclass
class Attempt:
    """Outcome of a single delivery attempt."""

    status: int | None
    error: str | None


@dataclass
class DeliveryResult:
    """Outcome of a delivery, including every attempt that was made."""

    status: int
    attempts: list[Attempt] = field(default_factory=list)


class DeliveryError(Exception):
    """Raised when a webhook delivery fails and will not be retried further."""

    def __init__(self, message: str, attempts: list[Attempt]) -> None:
        super().__init__(message)
        self.attempts = attempts


def _send_once(url: str, body: bytes, payload_json: str) -> int:
    """Make one POST attempt and return the status code."""
    request = urllib.request.Request(url, data=body, method="POST")
    request.add_header("X-Signature", sign(payload_json))
    with urllib.request.urlopen(request, timeout=REQUEST_TIMEOUT_SECONDS) as response:
        return response.status


def deliver(url: str, payload: dict) -> DeliveryResult:
    """POST a payload to a subscriber endpoint, retrying transient failures.

    A 5xx response or a connection/timeout error is retried up to
    MAX_ATTEMPTS times with exponential backoff. A 4xx response is treated
    as final and raised immediately without retrying.
    """
    payload_json = json.dumps(payload)
    body = payload_json.encode()
    attempts: list[Attempt] = []

    for attempt_number in range(1, MAX_ATTEMPTS + 1):
        logger.info("delivering %s to %s (attempt %d)", new_delivery_id(), url, attempt_number)
        try:
            status = _send_once(url, body, payload_json)
        except urllib.error.HTTPError as exc:
            attempts.append(Attempt(status=exc.code, error=str(exc)))
            if exc.code < 500:
                raise DeliveryError(
                    f"delivery to {url} failed with status {exc.code}", attempts
                ) from exc
        except OSError as exc:
            # Covers URLError (DNS/connection failures) and socket timeouts, both retryable.
            attempts.append(Attempt(status=None, error=str(exc)))
        else:
            attempts.append(Attempt(status=status, error=None))
            return DeliveryResult(status=status, attempts=attempts)

        if attempt_number < MAX_ATTEMPTS:
            time.sleep(BACKOFF_BASE_SECONDS * (2 ** (attempt_number - 1)))

    raise DeliveryError(
        f"delivery to {url} failed after {len(attempts)} attempts", attempts
    )

